const asOf = "2026-11-05";
type I = Omit<InstitutionInput, "kind" | "asOf">;
const i = (x: I): InstitutionInput => ({ kind: "institution", asOf, ...x });
type C = Omit<CollectionInput, "kind" | "asOf">;
const col = (x: C): CollectionInput => ({ kind: "collection", asOf, ...x });

/**
 * Rare-cancer foundations and nonprofits, November 2026. Before this round the corpus held no record of the Rare Cancer
 * Research Foundation or its tissue-donation platform Pattern.org, and few of the disease-specific foundations that serve
 * rare cancers. The denominators, each read as raw HTML on 5 November 2026:
 *
 * - the Rare Cancer Research Foundation's own list of patient advocacy partners (https://rarecancer.org/patients-advocacy-partners);
 * - NCI-CONNECT's list of current non-profit partners for rare brain and spine tumours
 *   (https://www.cancer.gov/rare-brain-spine-tumor/refer-participate/partnerships);
 * - rare-cancer coalitions, and disease-specific foundations for the rare cancers the corpus has pages for.
 *
 * Every fact is from the organisation's own pages or its charity regulator record (the IRS record via ProPublica
 * Nonprofit Explorer for US organisations, the Charity Commission for England and Wales, the Australian Business
 * Register for Australia). Coordinates are city-centre approximations. Charities use institutionType "consortium", as
 * the other charity files do. Founding years appear only where a page states one; otherwise the IRS ruling date is
 * given as what it is.
 *
 * Not added, and why: Rare Cancers Europe (its site failed a certificate check on 5 November 2026 and the newest archived
 * copy is from June 2023); the Rare Cancer Alliance at rare-cancer.org (a volunteer website whose about page was last
 * updated in 2011, with no IRS record found under that name); NORD and Global Genes (rare-disease bodies rather than
 * cancer ones; NORD's member list refused an automated request and has no archived copy, and Global Genes' alliance
 * list is for members only).
 */
const irs = (ein: string) => ({ label: "IRS record (via ProPublica Nonprofit Explorer)", url: `https://projects.propublica.org/nonprofits/organizations/${ein}` });
const REG = (n: string) => `https://register-of-charities.charitycommission.gov.uk/en/charity-search/-/charity-details/${n}`;
const reg = (n: string) => ({ label: "Charity Commission register entry", url: REG(n) });
const RCRF_PARTNERS = { label: "Rare Cancer Research Foundation: patient advocacy partners", url: "https://rarecancer.org/patients-advocacy-partners" };
